contract SimpleLending {
    CurvyPuppetOracle public oracle;
    ERC20 public collateralToken;
    ERC20 public loanToken;
    mapping(address => uint256) public collateralDeposited;
    mapping(address => uint256) public debt;

    constructor(address _oracle, address _collateralToken, address _loanToken) {
        oracle = CurvyPuppetOracle(_oracle);
        collateralToken = ERC20(_collateralToken);
        loanToken = ERC20(_loanToken);
    }

    function depositCollateral(uint256 amount) external {
        collateralToken.transferFrom(msg.sender, address(this), amount);
        collateralDeposited[msg.sender] += amount;
    }

    function borrow(uint256 amount) external {
        uint256 collateral = collateralDeposited[msg.sender];
        (uint256 price, ) = oracle.getPrice(address(collateralToken));
        uint256 collateralValue = (collateral * price) / 1e18;
        uint256 maxBorrow = (collateralValue * 50) / 100;
        require(amount <= maxBorrow, "Exceeds max borrow");
        loanToken.transfer(msg.sender, amount);
        debt[msg.sender] += amount;
    }
}

contract OracleManipulationTest is Test {
