        lending = new SimpleLending(address(oracle), address(dvt), address(weth));

        vm.prank(owner);
        oracle.setPrice(address(dvt), 1 ether, block.timestamp + 1 days);
    }

    function testOracleManipulationLeadsToExcessiveBorrow() public {
        vm.prank(user);
        dvt.approve(address(lending), 10 ether);
        lending.depositCollateral(10 ether);

        vm.prank(user);
        lending.borrow(5 ether);

        assertEq(weth.balanceOf(user), 5 ether);
        assertEq(lending.debt(user), 5 ether);

